package dev.raven.backup;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.view.*;import android.widget.*;import java.io.*;import org.json.*;
public class SettingsUiTest extends Instrumentation {
 Bundle args;public void onCreate(Bundle b){args=b;super.onCreate(b);start();}
 Button find(View v,String label){if(v instanceof Button&&label.contentEquals(((Button)v).getText()))return (Button)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){Button found=find(g.getChildAt(i),label);if(found!=null)return found;}}return null;}
 public void onStart(){Bundle result=new Bundle();try{MainActivity a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(()->a.showSection("Settings"));if(find(a.content,"Export settings")==null||find(a.content,"Import settings")==null)throw new AssertionError("buttons absent");
  String picker=args==null?null:args.getString("picker");if(picker!=null){runOnMainSync(()->find(a.content,picker.equals("export")?"Export settings":"Import settings").performClick());Thread.sleep(16000);getUiAutomation().executeShellCommand("input keyevent 4").close();result.putString("picker","Opened and cancelled "+picker+" picker");finish(-1,result);return;}
  File file=new File(a.getFilesDir(),"settings-transfer-ui-test.json");runOnMainSync(()->a.exportSettings(Uri.fromFile(file)));for(int i=0;i<200;i++){Thread.sleep(100);boolean[] busy={true};runOnMainSync(()->busy[0]=a.busy);if(!busy[0]&&!OperationService.running())break;}if(!file.isFile())throw new AssertionError("export missing");try(InputStream in=new FileInputStream(file)){SettingsTransfer.read(in);}sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);
  String before=SettingsTransfer.export(a).toString();runOnMainSync(()->a.importSettings(Uri.fromFile(file)));for(int i=0;i<200;i++){Thread.sleep(100);boolean[] busy={true};runOnMainSync(()->busy[0]=a.busy);if(!busy[0]&&!OperationService.running())break;}Thread.sleep(500);sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);JSONObject old=new JSONObject(before),now=SettingsTransfer.export(a);old.remove("exportedAt");now.remove("exportedAt");if(!old.toString().equals(now.toString()))throw new AssertionError("cancel changed preferences");file.delete();result.putString("result","PASS settings buttons, real resolver JSON export/read, themed import review and Cancel preserved actual preferences");finish(-1,result);
 }catch(Throwable t){result.putString("error",android.util.Log.getStackTraceString(t));finish(0,result);}}
}
